func captureOutput(f func() error) (string, error) {
	reader, writer, err := os.Pipe()
	if err != nil {
		return "", err
	}

	stdout := os.Stdout
	stderr := os.Stderr
	defer func() {
		os.Stdout = stdout
		os.Stderr = stderr
	}()

	os.Stdout = writer
	os.Stderr = writer

	out := make(chan string)
	wg := new(sync.WaitGroup)
	wg.Add(1)
	go func() {
		var buf bytes.Buffer
		wg.Done()
		_, _ = io.Copy(&buf, reader)
		out <- buf.String()
	}()

	wg.Wait()
	err = f()
	writer.Close()

	return <-out, err
}

func TestMarshallUnmarshall(t *testing.T) {
	spec := Spec{
		Version: "v1",
		Hooks: HooksMap{
			"hook0": []HookSpec{
				{
					Workdir: "/wherever0",
					Command: "whatever0",
					Args:    []string{"a0", "a1"},
					Envs: EnvsMap{
						"env0": "val0",
						"env1": "val1",
					},
				},
				{
					Workdir: "/wherever1",
					Command: "whatever1",
					Args:    []string{"a0", "a1"},
					Envs: EnvsMap{
						"env0": "val0",
						"env1": "val1",
					},
				},
			},
			"hook1": []HookSpec{
				{
					Workdir: "/wherever0",
					Command: "whatever0",
					Args:    []string{"a0", "a1"},
					Envs: EnvsMap{
						"env0": "val0",
						"env1": "val1",
					},
				},
				{
					Workdir: "/wherever1",
					Command: "whatever1",
					Args:    []string{"a0", "a1"},
					Envs: EnvsMap{
						"env0": "val0",
						"env1": "val1",
					},
				},
			},
		},
	}

	y, err := yaml.Marshal(spec)
	require.Nil(t, err, "Unexpected failure yaml.Marshal")

	s := Spec{}
	err = yaml.Unmarshal(y, &s)
	require.Nil(t, err, "Unexpected failure yaml.Unmarshal")
	require.Equal(t, spec, s)
}

func TestRunHooks(t *testing.T) {
	testCases := []struct {
		Description     string
		Hook            HookSpec
		expectedOutput  string
		expectedFailure bool
	}{
		{
			"Echo Hello",
			HookSpec{
				Command: "/bin/sh",
				Args:    []string{"-c", "echo Hello"},
			},
			"Hello\n",
			false,
		},
		{
			"Nonexistent Command",
			HookSpec{
				Command: "/doesnotexist",
			},
			"",
			true,
		},
	}
	for _, tc := range testCases {
		t.Run(tc.Description, func(t *testing.T) {
			output, err := captureOutput(func() error {
				return tc.Hook.Run(EnvsMap{}, true)
			})
			if !tc.expectedFailure {
				require.Nil(t, err, "Unexpected failure Hook.Run")
				require.Equal(t, tc.expectedOutput, output)
			} else {
				require.NotNil(t, err, "Unexpected success Hook.Run")
			}
		})
	}
}

