func TestSpec(t *testing.T) {
	testCases := []struct {
		Description     string
		Spec            string
		expectedFailure bool
	}{
		{
			"Empty",
			"",
			false,
		},
		{
			"Well formed",
			`{
				"version": "v1",
				"mig-configs": {
					"all-disabled": [{
						"devices": "all",
						"mig-enabled": false
					}]
				}
			}`,
			false,
		},
		{
			"Only version field",
			`{
				"version": "v1"
			}`,
			false,
		},
		{
			"Well formed - wrong version",
			`{
				"version": "v2",
				"mig-configs": {
					"all-disabled": [{
						"devices": "all",
						"mig-enabled": false
					}]
				}
			}`,
			true,
		},
		{
			"Only version field - wrong versiomn",
			`{
				"version": "v2"
			}`,
			true,
		},
		{
			"Missing version field",
			`{
				"mig-configs": {
					"all-disabled": [{
						"devices": "all",
						"mig-enabled": false
					}]
				}
			}`,
			true,
		},
		{
			"Erroneous field",
			`{
				"bogus": "field",
				"version": "v1",
				"mig-configs": {
					"all-disabled": [{
						"devices": "all",
						"mig-enabled": false
					}]
				}
			}`,
			true,
		},
		{
			"Empty 'mig-configs'",
			`{
				"version": "v1",
				"mig-configs": {}
			}`,
			true,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.Description, func(t *testing.T) {
			s := Spec{}
			err := yaml.Unmarshal([]byte(tc.Spec), &s)
			if tc.expectedFailure {
				require.NotNil(t, err, "Unexpected success yaml.Unmarshal")
			} else {
				require.Nil(t, err, "Unexpected failure yaml.Unmarshal")
			}
		})
	}
}

func TestMigConfigSpec(t *testing.T) {
	testCases := []struct {
		Description     string
		Spec            string
		expectedFailure bool
	}{
		{
			"Empty",
			"",
			false,
		},
		{
			"Well formed",
			`{
				"devices": "all",
				"mig-enabled": true,
				"mig-devices": {
					"1g.5gb": 2
				}
			}`,
			false,
		},
		{
			"Well formed with filter",
			`{
				"device-filter": "MODEL",
				"devices": "all",
				"mig-enabled": true,
				"mig-devices": {
					"1g.5gb": 2
				}
			}`,
			false,
		},
		{
			"Well formed with multi-filter",
			`{
				"device-filter": ["MODEL1", "MODEL2"],
				"devices": "all",
				"mig-enabled": true,
				"mig-devices": {
					"1g.5gb": 2
				}
			}`,
			false,
		},
		{
			"Missing 'devices'",
			`{
				"mig-enabled": true,
				"mig-devices": {
					"1g.5gb": 2
				}
			}`,
			true,
		},
		{
			"Missing 'mig-enabled'",
			`{
				"devices": "all",
				"mig-devices": {
					"1g.5gb": 2
				}
			}`,
			true,
		},
		{
			"Missing 'mig-devices', enabled: false",
			`{
				"devices": "all",
				"mig-enabled": false,
			}`,
			false,
		},
		{
			"Missing 'mig-devices', enabled: true",
			`{
				"devices": "all",
				"mig-enabled": true,
			}`,
			true,
		},
		{
			"'mig-devices' formatted correctly",
			`{
				"devices": "all",
				"mig-enabled": true,
				"mig-devices": {
					"1g.5gb": 2
				}
			}`,
			false,
		},
		{
			"'mig-devices' formatted incorrectly",
			`{
				"devices": "all",
				"mig-enabled": true,
				"mig-devices": {
					"bogus": 2
				}
			}`,
			true,
		},
		{
			"Erroneous field",
			`{
				"bogus": "field",
				"devices": "all",
				"mig-enabled": false,
			}`,
			true,
		},
		{
			"'devices' string == all",
			`{
				"devices": "all",
				"mig-enabled": false,
			}`,
			false,
		},
		{
			"'devices' string != all",
			`{
				"devices": "bogus",
				"mig-enabled": false,
			}`,
			true,
		},
		{
			"'devices' []int",
			`{
				"devices": [0,1,2,3],
				"mig-enabled": false,
			}`,
			false,
		},
		{
			"'devices' not string for []int",
			`{
				"devices": {},
				"mig-enabled": false,
			}`,
			true,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.Description, func(t *testing.T) {
			var s MigConfigSpec
			err := yaml.Unmarshal([]byte(tc.Spec), &s)
			if tc.expectedFailure {
				require.NotNil(t, err, "Unexpected success yaml.Unmarshal")
			} else {
				require.Nil(t, err, "Unexpected failure yaml.Unmarshal")
			}
		})
	}
}

